STRUCTURAL = {'properties', 'items', 'allOf', 'if', 'then', 'else'}
RESOURCE = 'produkt/vertraege/v2/ereignis.schema.json'
UUID_PATTERN = HIST['properties']['eventId']['pattern']
BASE = [(i, x) for i, x in enumerate(FIELDS['baseNodes']) if x['contract'] == 'ereignis']
ADDITIONS = [(i, x) for i, x in enumerate(FIELDS['additionalFields']) if x['contract'] == 'ereignis']


def esc(s):
    return s.replace('~', '~0').replace('/', '~1')


def nid(ptr):
    return 'ereignis#' + ptr


def citation(path, pointer=None, lines=None):
    x = {'path': path, 'sha256': SHA[path]}
    if pointer is not None:
        x['jsonPointer'] = pointer
    if lines is not None:
        x['lines'] = lines
    return x


def field_citation(ptr):
    return citation('contract-fields.json', ptr)


def contract_citation(*lines):
    return citation('CONTRACT.md', lines=list(lines))


def canonical(value):
    return digest(json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8'))


def local(value):
    return {k: v for k, v in value.items() if k not in STRUCTURAL}


# Reine Baumadressierung: keine Pruefung eines Ereignisses gegen Bedingungen.
FLAT = {}

def walk(value, ptr='', immediate_required=False, location=None, guards=None, parent=None, edge='ROOT'):
    location = [] if location is None else location
    guards = [] if guards is None else guards
    row = {'value': value, 'required': immediate_required, 'location': location,
           'guards': guards, 'parent': parent, 'edge': edge, 'children': []}
    FLAT[ptr] = row
    for key, child in value.get('properties', {}).items():
        p = ptr + '/properties/' + esc(key)
        row['children'].append(p)
        walk(child, p, key in value.get('required', []), location + [{'property': key}], guards, ptr, 'PROPERTY')
    if 'items' in value:
        p = ptr + '/items'
        row['children'].append(p)
        walk(value['items'], p, True, location + [{'elementOf': nid(ptr)}], guards, ptr, 'ARRAY_ELEMENT')
    for i, child in enumerate(value.get('allOf', [])):
        p = ptr + '/allOf/' + str(i)
        row['children'].append(p)
        walk(child, p, False, location, guards, ptr, 'CONJUNCT')
    for key in ('if', 'then', 'else'):
        if key in value:
            p = ptr + '/' + key
            row['children'].append(p)
            guard = {'conditionOwnerNodeId': nid(ptr), 'arm': key.upper(),
                     'predicateNodeId': nid(ptr + '/if')}
            walk(value[key], p, False, location, guards + [guard], ptr, key.upper())


