def primary_declaration(ptr):
    """Adressiert denselben Datenort, ohne fachliche Bedingungen auszuwerten."""
    row = FLAT[ptr]
    loc = row['location']
    if not loc:
        return ''
    if loc[0].get('property') == 'payload':
        if not ptr.startswith('/allOf/'):
            return '/properties/payload'
        branch = int(ptr.split('/')[2])
        p = payload(MAIN_BRANCH[BRANCH_TYPES[branch]])
        rest = loc[1:]
    else:
        p = ''
        rest = loc
    for piece in rest:
        p += '/properties/' + esc(piece['property']) if 'property' in piece else '/items'
    return p


def presence(ptr, old=False):
    if ptr == '':
        return {'mode': 'ROOT', 'requiredInImmediateSchemaObject': False}
    row = FLAT[ptr]
    if row['edge'] != 'PROPERTY':
        return {'mode': 'ARRAY_ELEMENT' if row['edge'] == 'ARRAY_ELEMENT' else 'CONSTRAINT_NODE',
                'requiredInImmediateSchemaObject': row['required'],
                'note': 'Das historische requiredInParent bei items ist Traversierungsmetadatum, kein zusaetzliches Datenfeld.' if row['edge'] == 'ARRAY_ELEMENT' else 'Bedingungsknoten sind weder optionale noch erforderliche Datenfelder.'}
    primary = primary_declaration(ptr)
    if any(g['arm'] == 'IF' for g in row['guards']):
        return {'mode': 'PREDICATE', 'requiredInImmediateSchemaObject': row['required'],
                'dataDeclarationNodeId': nid(primary),
                'note': 'Praedikat auf dem adressierten Datenfeld; keine unabhaengige Freigabe oder eigene optionale Kopie.'}
    if primary == payload(4, 'fromRecognitionId'):
        return {'mode': 'CONDITIONAL', 'requiredInImmediateSchemaObject': False,
                'requiredWhen': {'fieldNodeId': nid(payload(4, 'origin')), 'values': ['automatisch_uebernommen', 'bestaetigt', 'korrigiert']},
                'forbiddenWhen': {'fieldNodeId': nid(payload(4, 'origin')), 'value': 'direkt'},
                'conditionOwnerNodeId': nid(payload(4) + '/allOf/0')}
    if primary == payload(12, 'sinceSeq'):
        return {'mode': 'CONDITIONAL', 'requiredInImmediateSchemaObject': False,
                'requiredWhen': {'fieldNodeId': nid(payload(12, 'kind')), 'value': 'gap'},
                'forbiddenForOtherEnumValues': ['interruption', 'clock_unreliable', 'permission_missing'],
                'conditionOwnerNodeId': nid(payload(12) + '/allOf/0')}
    if primary in (payload(14, 'eventIds'), ADD_PATHS[3]) and not old:
        return {'mode': 'OPTIONAL_IN_AT_LEAST_ONE_GROUP', 'requiredInImmediateSchemaObject': False,
                'groupOwnerNodeId': nid(payload(14)),
                'groupMemberNodeIds': [nid(payload(14, 'eventIds')), nid(ADD_PATHS[3])],
                'note': 'Mindestens eine vorhandene Liste; jede vorhandene Liste nichtleer. Kein genau-eins-Gebot.'}
    required = FLAT[primary]['required']
    # Typ-Payload und Akteur sind bereits in der gemeinsamen Huelle Pflicht.
    if len(row['location']) == 1:
        field = row['location'][0]['property']
        required = field in HIST['required']
        owner = ''
    else:
        owner = FLAT[primary]['parent']
    return {'mode': 'REQUIRED' if required else 'OPTIONAL',
            'requiredInImmediateSchemaObject': row['required'],
            'dataDeclarationNodeId': nid(primary), 'presenceOwnerNodeId': nid(owner),
            'note': 'Pflicht relativ zum vorhandenen Elternobjekt und zum expliziten Bedingungspfad; ein optionales monotonic wird dadurch nicht global erforderlich.'}


def links(ptr, old=False):
    row = FLAT[ptr]
    children = [p for p in row['children'] if not old or p not in ADDED_LOCAL]
    value = row['value']
    result = {'parentNodeId': None if row['parent'] is None else nid(row['parent']),
              'edge': row['edge'], 'childNodeIds': [nid(p) for p in children],
              'activationPath': row['guards'], 'instanceLocation': row['location'],
              'schemaRefTargets': []}
    primary = primary_declaration(ptr)
    result['dataDeclarationNodeId'] = nid(primary)
    if 'if' in value:
        result['conditionalArms'] = {arm: nid(ptr + '/' + arm) for arm in ('if', 'then', 'else') if arm in value}
        result['conditionCombiner'] = 'IF_THEN_ELSE; nur der passende Zweig, kein pauschales Und aller Zweige'
    if 'allOf' in value:
        result['allOfNodeIds'] = [nid(ptr + '/allOf/' + str(i)) for i in range(len(value['allOf']))]
    if 'not' in value:
        result['inlineNegation'] = deepcopy(value['not'])
        result['inlineNegationPointer'] = ptr + '/not'
        result['inlineNegationPolicy'] = 'Exakt erhaltenes Fragment des historischen Knotenconstraints, keine vergessene Wildcard und kein separat gezaehlter baseNode.'
    return result


def json_type(x):
    if x is None:
        return 'null'
    if isinstance(x, bool):
        return 'boolean'
    if isinstance(x, str):
        return 'string'
    if isinstance(x, int):
        return 'integer'
    if isinstance(x, float):
        return 'number'
    if isinstance(x, list):
        return 'array'
    return 'object'


def facets(ptr, constraints, old=False):
    row = FLAT[ptr]
    literals = constraints.get('enum', [constraints['const']] if 'const' in constraints else [])
    fields = [p.rsplit('/', 1)[1] for p in row['children'] if FLAT[p]['edge'] == 'PROPERTY' and (not old or p not in ADDED_LOCAL)]
    closure = 'CLOSED_HERE' if constraints.get('additionalProperties') is False else 'NO_LOCAL_CLOSURE'
    result = {
        'type': {'declared': constraints.get('type'), 'impliedByLiterals': sorted({json_type(x) for x in literals}),
                 'dataDeclarationNodeId': nid(primary_declaration(ptr)),
                 'note': 'null bei declared bedeutet keine eigene Typdeklaration, nicht Erlaubnis fuer den JSON-Wert null. Enum/const und adressierter Kontext bleiben wirksam.'},
        'enum': {'specified': 'enum' in constraints, 'values': constraints.get('enum')},
        'const': {'specified': 'const' in constraints, 'value': constraints.get('const')},
        'numeric': {k: constraints.get(k) for k in ('minimum', 'maximum', 'exclusiveMinimum', 'exclusiveMaximum', 'multipleOf')},
        'string': {k: constraints.get(k) for k in ('minLength', 'maxLength', 'pattern', 'format')},
        'array': {k: constraints.get(k) for k in ('minItems', 'maxItems', 'uniqueItems')},
        'object': {'closure': closure, 'declaredFields': fields,
                   'requiredFields': constraints.get('required', []),
                   'additionalProperties': constraints.get('additionalProperties'),
                   'note': 'Ein Bedingungsfragment ohne eigene Schliessung oeffnet nicht das zugehoerige bereits geschlossene Datenobjekt.'},
    }
    if ptr == '/properties/payload':
        result['object']['closure'] = 'CLOSED_BY_EXACT_EVENT_TYPE_BRANCH'
        result['object']['typeBranches'] = [{'eventType': t, 'payloadNodeId': nid(payload(i))} for i, t in enumerate(EVENT_TYPES)]
    if ptr == '/properties/monotonic/properties/ns' and not old:
        result['string']['decimalValueRange'] = {'minimumInclusive': '0', 'maximumInclusive': '18446744073709551615',
                                                 'leadingZeroAllowedOnlyFor': '0', 'signAllowed': False}
    return result


