def build_nodes():
    nodes = []
    base_by_ptr = {x['schemaPointer']: (i, x) for i, x in BASE}
    for ptr, tree in FLAT.items():
        added = ptr in ADDED_LOCAL
        if added:
            idx = next(i for i, p in ADD_PATHS.items() if ptr == p or ptr == p + '/items')
            src = dict(ADDITIONS)[idx]
            old_constraints = None
            new_constraints = deepcopy(ADDED_LOCAL[ptr])
            decision = 'ADD'
            origin = {'fieldTable': field_citation('/additionalFields/' + str(idx)),
                      'declaredPathLiteral': src['path'], 'declaredField': deepcopy(src),
                      'expansion': 'ARRAY_ELEMENT_FROM_DECLARED_array<uuid>' if ptr.endswith('/items') else 'DECLARED_FIELD'}
            sources = [field_citation('/additionalFields/' + str(idx)), contract_citation(14 if ptr.endswith('/items') else 15 if idx in (1, 2) else 9 if idx == 0 else 7)]
            reason = 'Bereits deklariertes Feld eindeutig adressiert.' if not ptr.endswith('/items') else 'Expliziter Elementknoten der schon deklarierten UUID-Liste; kein zusaetzliches Datenfeld und keine neue Erweiterung.'
        else:
            idx, src = base_by_ptr[ptr]
            old_constraints = deepcopy(src['constraints'])
            new_constraints = deepcopy(old_constraints)
